import { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { useNavigate, useOutletContext } from 'react-router-dom';
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Users,
  UserPlus,
  ArrowLeft,
  Loader2,
  ShieldCheck,
  Ban,
  CheckCircle2,
  History,
  KeyRound,
  Clock,
  UserCheck,
  UserX,
} from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';
import { getAllAccounts, upsertAccount, removeAccount } from '@/hooks/useAuth';
import { _readAccounts, _writeAccounts } from '@/hooks/useAuth';
import type { AuthAccountRecord } from '@/hooks/useAuth';
import api from '@/lib/api';
import { toast } from 'sonner';
import { logger, scopedStorage } from '@lark-apaas/client-toolkit-lite';
import type { ThemeConfig } from '@/lib/theme';
import type { FestivalBadge } from '@/lib/theme';

// 后端账号接口返回的字段结构
interface SubAccount {
  id: number;
  username: string;
  nickname: string;
  role: string;
  status: 'active' | 'disabled' | 'pending' | 'rejected';
  checkin_days: number;
  task_count: number;
  note_count: number;
  lastLogin: string | null;      // 后端字段名：lastLogin
  createdAt: string;             // 后端字段名：createdAt
  last_login_at: string | null;  // 兼容旧字段名
  created_at: string;            // 兼容旧字段名
  hours_since_login: number;
  is_owner?: boolean;
}

interface LoginLog {
  id: number;
  ip: string;
  device_fingerprint: string | null;
  status: string;
  reason: string | null;
  created_at: string;
}

export default function TeamManagementPage() {
  const navigate = useNavigate();
  const { user, isLoggedIn, isLoading: authLoading, approveAccount, rejectAccount, updateAccountPassword } = useAuth();
  const { theme } = useOutletContext<{ theme: ThemeConfig; festival: FestivalBadge }>();
  const [list, setList] = useState<SubAccount[]>([]);
  const [loading, setLoading] = useState(true);
  const [addOpen, setAddOpen] = useState(false);
  const [logsOpen, setLogsOpen] = useState(false);
  const [resetOpen, setResetOpen] = useState(false);
  const [confirmStatus, setConfirmStatus] = useState<{ username: string; status: string } | null>(null);
  const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null);
  const [currentUserId, setCurrentUserId] = useState<number | null>(null);
  const [logs, setLogs] = useState<LoginLog[]>([]);
  const [logsLoading, setLogsLoading] = useState(false);
  const [newUsername, setNewUsername] = useState('');
  const [newNickname, setNewNickname] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const [resetPassword, setResetPassword] = useState('');
  const [resetSubmitting, setResetSubmitting] = useState(false);

  // 审批相关
  const [approveConfirm, setApproveConfirm] = useState<string | null>(null);
  const [rejectConfirm, setRejectConfirm] = useState<string | null>(null);
  const [approveSubmitting, setApproveSubmitting] = useState(false);
  const [rejectSubmitting, setRejectSubmitting] = useState(false);
  // 记录上次待审批数量，新增加时弹 toast 提醒
  const lastPendingRef = useRef<number>(0);

  // 从 Outlet context 拿 theme

  // 权限校验
  useEffect(() => {
    if (authLoading) return;
    if (!isLoggedIn) {
      navigate('/');
      toast.info('请先登录');
      return;
    }
    if (user?.role !== 'super_admin' && user?.role !== 'admin') {
      navigate('/');
      toast.error('无权限访问团队管理');
      return;
    }
    loadList();
  }, [authLoading, isLoggedIn, user?.role]);

  // 把后端返回的字段名统一成组件可用格式（兼容 lastLogin/createdAt 和 last_login_at/created_at）
  function normalizeAccount(a: any, currentUsername: string): SubAccount {
    const lastLogin = a.lastLogin || a.last_login_at || null;
    const createdAt = a.createdAt || a.created_at || a.register_at || new Date().toISOString();
    const now = Date.now();
    return {
      id: a.id || 0,
      username: a.username,
      nickname: a.nickname || a.username,
      role: a.role || 'user',
      status: a.status || 'active',
      checkin_days: a.checkin_days ?? 0,
      task_count: a.task_count ?? 0,
      note_count: a.note_count ?? 0,
      lastLogin,
      createdAt,
      last_login_at: lastLogin,
      created_at: createdAt,
      hours_since_login: lastLogin
        ? Math.floor((now - new Date(lastLogin).getTime()) / 3600000)
        : 9999,
      is_owner: a.role === 'super_admin' || a.username === currentUsername,
    };
  }

  const loadList = async () => {
    setLoading(true);
    try {
      const currentUsername = user?.username || '';
      let accounts: SubAccount[] = [];
      let useLocal = false;

      try {
        const res = await api.get('/auth/accounts');
        const data = res.data as any;
        const rawList: any[] = Array.isArray(data) ? data : (data.accounts || data.list || []);
        accounts = rawList.map(a => normalizeAccount(a, currentUsername));

        // 关键修复：把后端拿到的全量账号同步写入本地缓存
        // 这样在 A 电脑注册、B 电脑审阅时，B 电脑的 approve/reject 本地同步也能生效
        const allLocal = rawList.map((a: any, idx: number): AuthAccountRecord => ({
          id: a.id || idx + 1,
          username: a.username,
          nickname: a.nickname || a.username,
          role: a.role || 'user',
          register_at: a.created_at || a.createdAt || a.register_at || new Date().toISOString(),
          last_login_at: a.last_login_at || a.lastLogin || '',
          status: a.status || 'active',
          parent_username: a.parent_id ? undefined : undefined,
        }));
        // 用本地现有密码哈希回填（避免清掉本地降级登录用的密码）
        const existingLocal = _readAccounts();
        const passwordMap = new Map<string, string>();
        for (const acc of existingLocal) {
          if (acc.password) passwordMap.set(acc.username, acc.password);
        }
        const merged = allLocal.map(a => ({
          ...a,
          password: passwordMap.get(a.username),
        }));
        _writeAccounts(merged);
      } catch (err) {
        // 接口失败降级：从本地账号列表读取
        useLocal = true;
        logger.warn('[team] 账号列表接口失败，降级到本地', String(err));
      }

      if (useLocal || accounts.length === 0) {
        const localAccounts = getAllAccounts();
        accounts = localAccounts.map((a: AuthAccountRecord, idx: number) =>
          normalizeAccount({
            id: a.id || idx + 1,
            username: a.username,
            nickname: a.nickname || a.username,
            role: a.role,
            status: a.status,
            lastLogin: a.last_login_at || null,
            createdAt: a.register_at,
          }, currentUsername)
        );
      }

      // 确保当前主账号也在列表里，标记出来
      if (user && !accounts.some(a => a.username === user.username)) {
        accounts.unshift(normalizeAccount({
          id: user.id || 0,
          username: user.username,
          nickname: user.nickname,
          role: user.role,
          status: 'active',
          lastLogin: new Date().toISOString(),
          createdAt: new Date(Date.now() - 30 * 24 * 3600 * 1000).toISOString(),
        }, currentUsername));
      }

      setList(accounts);
    } catch (err: any) {
      logger.error('[team] 加载账号列表失败', String(err.message || err));
      toast.error('加载失败');
    } finally {
      setLoading(false);
    }
  };

  const handleAdd = async () => {
    if (!newUsername || !newPassword) {
      toast.error('请填写用户名和密码');
      return;
    }
    if (newPassword.length < 6) {
      toast.error('密码至少6位');
      return;
    }
    setSubmitting(true);
    try {
      let apiSuccess = false;
      try {
        const res = await api.post('/auth/accounts', {
          action: 'add',
          username: newUsername,
          password: newPassword,
          nickname: newNickname || undefined,
          adminUser: user?.username || '',
        });
        const data = res.data as any;
        if (data && data.success === false) {
          throw new Error(data.error || '创建失败');
        }
        apiSuccess = true;
      } catch (e: any) {
        // 409 = 用户名重复
        if (e?.response?.status === 409 || e?.message?.includes('已存在') || e?.message?.includes('重复')) {
          toast.error('该用户名已存在');
          return;
        }
        // 其他错误降级到本地
        logger.warn('[team] 新增账号接口失败，降级到本地创建', String(e));
      }

      // 同步写入本地账号列表
      const now = new Date().toISOString();
      if (apiSuccess) {
        // 接口成功：以接口返回数据为准写入本地缓存
        const all = getAllAccounts();
        if (all.some(a => a.username === newUsername)) {
          toast.error('该用户名已存在');
          return;
        }
        upsertAccount({
          id: Date.now(),
          username: newUsername,
          nickname: newNickname || newUsername,
          role: 'sub_account',
          password: newPassword,
          register_at: now,
          last_login_at: '',
          status: 'active',
          parent_username: user?.username || undefined,
        });
      } else {
        // 降级模式：本地创建
        const all = getAllAccounts();
        if (all.some(a => a.username === newUsername)) {
          toast.error('该用户名已存在');
          return;
        }
        upsertAccount({
          id: Date.now(),
          username: newUsername,
          nickname: newNickname || newUsername,
          role: 'sub_account',
          password: newPassword,
          register_at: now,
          last_login_at: '',
          status: 'active',
          parent_username: user?.username || undefined,
        });
      }

      toast.success(apiSuccess ? '子账号创建成功' : '子账号创建成功（本地模式）');
      setAddOpen(false);
      setNewUsername('');
      setNewNickname('');
      setNewPassword('');
      loadList();
    } catch (err: any) {
      toast.error(err.message || '创建失败');
    } finally {
      setSubmitting(false);
    }
  };

  const handleStatusConfirm = async () => {
    if (!confirmStatus) return;
    const { username, status } = confirmStatus;
    try {
      let apiSuccess = false;
      try {
        await api.post('/auth/accounts', {
          action: 'toggle',
          username,
          adminUser: user?.username || '',
        });
        apiSuccess = true;
      } catch (e) {
        logger.warn('[team] 状态切换接口失败，降级到本地', String(e));
      }
      // 同步本地账号列表
      const all = getAllAccounts();
      const target = all.find(a => a.username === username);
      if (target) {
        target.status = status as 'active' | 'disabled';
        upsertAccount(target);
      }
      toast.success(status === 'active' ? '已启用' : '已禁用');
      setConfirmStatus(null);
      loadList();
    } catch (err: any) {
      toast.error(err.message || '操作失败');
    }
  };

  const handleDelete = async () => {
    if (!deleteConfirm) return;
    const username = deleteConfirm;
    try {
      let apiSuccess = false;
      let errorMsg = '';
      try {
        await api.delete(`/admin/users/${encodeURIComponent(username)}`);
        apiSuccess = true;
      } catch (e: any) {
        errorMsg = e?.response?.data?.error || e?.message || '删除失败';
        logger.warn('[team] 删除账号接口失败', String(e));
      }
      // 同步本地账号列表
      removeAccount(username);
      toast.success(apiSuccess ? '账号已删除，登录立即失效' : '已从本机移除（服务端未同步）');
      if (!apiSuccess && errorMsg) {
        toast.info(errorMsg);
      }
      setDeleteConfirm(null);
      loadList();
    } catch (err: any) {
      toast.error(err.message || '删除失败');
    }
  };

  const [resetUsername, setResetUsername] = useState('');
  const [resetAccountId, setResetAccountId] = useState<number | null>(null);

  const handleResetPassword = async () => {
    if (!resetAccountId || !resetUsername) return;
    if (!resetPassword || resetPassword.length < 6) {
      toast.error('密码至少6位');
      return;
    }
    setResetSubmitting(true);
    try {
      const result = await updateAccountPassword(resetAccountId, resetPassword);
      if (result === true) {
        toast.success('密码已更新，子账号下次登录需使用新密码');
      } else if (result === 'local') {
        toast.success('已在本机更新，但服务端未同步，建议稍后重试');
      } else {
        throw new Error('更新失败');
      }
      setResetOpen(false);
      setResetPassword('');
      setResetUsername('');
      setResetAccountId(null);
    } catch (err: any) {
      toast.error(err.message || '重置失败');
    } finally {
      setResetSubmitting(false);
    }
  };

  const handleApprove = async () => {
    if (!approveConfirm) return;
    setApproveSubmitting(true);
    try {
      const result = await approveAccount(approveConfirm, user?.username);
      if (!result.success) {
        throw new Error(result.error || '审批失败');
      }
      toast.success('已通过，该账号可正常登录');
      setApproveConfirm(null);
      loadList();
    } catch (err: any) {
      toast.error(err.message || '操作失败');
    } finally {
      setApproveSubmitting(false);
    }
  };

  const handleReject = async () => {
    if (!rejectConfirm) return;
    setRejectSubmitting(true);
    try {
      const result = await rejectAccount(rejectConfirm, user?.username);
      if (!result.success) {
        throw new Error(result.error || '操作失败');
      }
      toast.success('已拒绝，该账号无法登录');
      setRejectConfirm(null);
      loadList();
    } catch (err: any) {
      toast.error(err.message || '操作失败');
    } finally {
      setRejectSubmitting(false);
    }
  };

  const loadLogs = async (username: string) => {
    setResetUsername(username);
    setLogsLoading(true);
    setLogsOpen(true);
    try {
      // 优先尝试新接口路径
      const res = await api.get(`/auth/accounts/${encodeURIComponent(username)}/login-logs`);
      const data = res.data as any;
      setLogs(data.logs || data.list || []);
    } catch (err) {
      logger.warn('[team] 登录日志接口不可用', String(err));
      setLogs([]);
      toast.info('日志功能暂不可用');
    } finally {
      setLogsLoading(false);
    }
  };

  const isSuperAdmin = user?.role === 'super_admin';

  // 页面可见性变化时自动刷新（切回页面时刷新待审批列表）
  useEffect(() => {
    const onVisible = () => {
      if (document.visibilityState === 'visible' && isLoggedIn && isSuperAdmin) {
        loadList();
      }
    };
    document.addEventListener('visibilitychange', onVisible);
    return () => document.removeEventListener('visibilitychange', onVisible);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isLoggedIn, isSuperAdmin]);

  const totalStats = useMemo(() => {
    const active = list.filter(u => u.status === 'active').length;
    const pending = list.filter(u => u.status === 'pending').length;
    const today = new Date().toDateString();
    const todayNew = list.filter(u => {
      const t = u.createdAt || u.created_at;
      return t && new Date(t).toDateString() === today;
    }).length;
    const weekAgo = Date.now() - 7 * 24 * 3600 * 1000;
    const active7d = list.filter(u => {
      const t = u.lastLogin || u.last_login_at;
      return t && new Date(t).getTime() >= weekAgo;
    }).length;
    return { active, pending, todayNew, active7d };
  }, [list]);

  // 待审批数量变化通知：有新申请时弹 toast 提醒主账号
  useEffect(() => {
    const current = totalStats.pending;
    if (current > lastPendingRef.current && lastPendingRef.current > 0) {
      toast.info(`有 ${current - lastPendingRef.current} 个新的注册申请待审阅`, {
        action: {
          label: '去处理',
          onClick: () => {
            const el = document.getElementById('pending-section');
            if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
          },
        },
      });
    }
    lastPendingRef.current = current;
  }, [totalStats.pending]);

  const pendingList = useMemo(() => list.filter(u => u.status === 'pending'), [list]);
  const activeList = useMemo(() => list.filter(u => u.status !== 'pending'), [list]);

  if (!theme) {
    return null;
  }

  const p0Color = theme.priority?.p0 || theme.primaryDark;

  return (
    <div className="space-y-5">
      {/* 顶部：返回 + 标题 + 新增按钮 */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div className="flex items-center gap-3">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate(-1)}
            className="h-8 gap-1"
          >
            <ArrowLeft className="size-4" />
            返回
          </Button>
          <div>
            <div className="flex items-center gap-2">
              <Users className="size-5" style={{ color: theme.primary }} />
              <h1 className="text-lg font-bold">团队管理</h1>
            </div>
            <p className="text-xs text-muted-foreground mt-0.5">
              管理子账号、查看登录日志、重置密码
            </p>
          </div>
        </div>
        <Button
          size="sm"
          className="gap-1"
          onClick={() => setAddOpen(true)}
          style={{ backgroundColor: theme.primary }}
        >
          <UserPlus className="size-3.5" />
          新增子账号
        </Button>
      </div>

      {/* 统计概览 */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
        {[
          { label: '账号总数', value: list.length, icon: Users },
          { label: '活跃账号', value: totalStats.active, icon: CheckCircle2 },
          { label: '待审批', value: totalStats.pending, icon: Clock, highlight: true },
          { label: '近7日登录', value: totalStats.active7d, icon: ShieldCheck },
          { label: '今日新增', value: totalStats.todayNew, icon: KeyRound },
        ].map((stat, i) => (
          <Card
            key={i}
            className="border-0"
            style={{
              backgroundColor: theme.ui.glassBg,
              backdropFilter: 'blur(12px) saturate(180%)',
              WebkitBackdropFilter: 'blur(12px) saturate(180%)',
              boxShadow: theme.ui.glassShadow,
              border: `1px solid ${theme.ui.glassBorder || theme.ui.cardBorder}`,
            }}
          >
            <CardContent className="p-4">
              <div className="flex items-center gap-2 text-xs text-muted-foreground mb-1">
                <stat.icon className="size-3.5" style={{ color: stat.highlight && totalStats.pending > 0 ? p0Color : theme.primary }} />
                {stat.label}
              </div>
              <div
                className="text-2xl font-bold tabular-nums"
                style={{ color: stat.highlight && totalStats.pending > 0 ? p0Color : theme.primaryDark }}
              >
                {stat.value}
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* 待审批列表 */}
      {!loading && (
        <Card
          id="pending-section"
          className="border-0 overflow-hidden"
          style={{
            backgroundColor: theme.ui.glassBg,
            backdropFilter: 'blur(12px) saturate(180%)',
            WebkitBackdropFilter: 'blur(12px) saturate(180%)',
            boxShadow: theme.ui.glassShadow,
            border: `1px solid ${theme.ui.glassBorder || theme.ui.cardBorder}`,
          }}
        >
          <CardHeader className="pb-2">
            <CardTitle className="text-base flex items-center gap-2">
              <Clock className="size-4" style={{ color: p0Color }} />
              待审批账号
              <Badge className="text-[10px] ml-1" style={{ backgroundColor: p0Color + '15', color: p0Color }}>
                {pendingList.length} 个
              </Badge>
            </CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <div className="w-full overflow-x-auto">
               <Table>
                 <TableHeader>
                   <TableRow>
                     <TableHead className="whitespace-nowrap">账号</TableHead>
                     <TableHead className="whitespace-nowrap">昵称</TableHead>
                     <TableHead className="whitespace-nowrap">状态</TableHead>
                     <TableHead className="whitespace-nowrap">注册时间</TableHead>
                     <TableHead className="whitespace-nowrap text-right">操作</TableHead>
                   </TableRow>
                 </TableHeader>
                  <TableBody>
                    {pendingList.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={5} className="text-center py-8 text-muted-foreground text-xs">
                          暂无待审批账号
                        </TableCell>
                      </TableRow>
                    ) : (
                      pendingList.map((acc) => (
                        <TableRow key={acc.id}>
                          <TableCell className="font-medium">
                            <div className="flex items-center gap-2">
                              <span className="block truncate max-w-[120px]">{acc.username}</span>
                            </div>
                          </TableCell>
                          <TableCell>
                            <span className="block truncate max-w-[120px]">{acc.nickname || '-'}</span>
                          </TableCell>
                          <TableCell>
                            <Badge className="text-xs border-0" style={{ backgroundColor: p0Color + '12', color: p0Color }}>
                              <Clock className="size-3 mr-1" />
                              待审批
                            </Badge>
                          </TableCell>
                          <TableCell className="whitespace-nowrap text-xs text-muted-foreground">
                            {(acc.createdAt || acc.created_at)?.slice(0, 16).replace('T', ' ') || '-'}
                          </TableCell>
                          <TableCell className="text-right">
                            <div className="flex items-center justify-end gap-1">
                              <Button
                                variant="ghost"
                                size="sm"
                                className="h-7 text-xs px-2"
                                style={{ color: theme.primary }}
                                onClick={() => setApproveConfirm(acc.username)}
                              >
                                <UserCheck className="size-3.5 mr-1" />
                                通过
                              </Button>
                              <Button
                                variant="ghost"
                                size="sm"
                                className="h-7 text-xs px-2"
                                style={{ color: p0Color }}
                                onClick={() => setRejectConfirm(acc.username)}
                              >
                                <UserX className="size-3.5 mr-1" />
                                拒绝
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
              </Table>
            </div>
          </CardContent>
         </Card>
       )}

      {/* 子账号列表 */}
      <Card
        className="border-0 overflow-hidden"
        style={{
          backgroundColor: theme.ui.glassBg,
          backdropFilter: 'blur(12px) saturate(180%)',
          WebkitBackdropFilter: 'blur(12px) saturate(180%)',
          boxShadow: theme.ui.glassShadow,
          border: `1px solid ${theme.ui.glassBorder || theme.ui.cardBorder}`,
        }}
      >
        <CardHeader className="pb-2">
          <CardTitle className="text-base">子账号列表</CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          {loading ? (
            <div className="flex items-center justify-center py-16 text-muted-foreground text-sm">
              <Loader2 className="size-4 animate-spin mr-2" />
              加载中...
            </div>
          ) : activeList.length === 0 ? (
            <div className="text-center py-16 text-muted-foreground text-sm">
              暂无子账号，点击右上角「新增子账号」创建
            </div>
          ) : (
            <div className="w-full overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="whitespace-nowrap">账号</TableHead>
                    <TableHead className="whitespace-nowrap">角色</TableHead>
                    <TableHead className="whitespace-nowrap">昵称</TableHead>
                    <TableHead className="whitespace-nowrap">状态</TableHead>
                    <TableHead className="whitespace-nowrap">注册时间</TableHead>
                    <TableHead className="whitespace-nowrap">最后登录</TableHead>
                    <TableHead className="whitespace-nowrap">累计打卡</TableHead>
                    <TableHead className="whitespace-nowrap text-right">操作</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {activeList.map((acc) => (
                    <TableRow key={acc.id}>
                       <TableCell className="font-medium">
                         <div className="flex items-center gap-2">
                           <span className="block truncate max-w-[120px]">{acc.username}</span>
                           {acc.is_owner && acc.role === 'super_admin' && (
                             <Badge
                               className="text-[10px] border-0"
                               style={{
                                 backgroundColor: theme.primary + '15',
                                 color: theme.primary,
                               }}
                             >
                               主账号
                             </Badge>
                           )}
                         </div>
                       </TableCell>
                       <TableCell>
                         <Badge variant="outline" className="text-[11px] font-normal">
                           {acc.role === 'super_admin' ? '超级管理员' : acc.role === 'admin' ? '管理员' : acc.role === 'sub_account' ? '子账号' : '成员'}
                         </Badge>
                       </TableCell>
                       <TableCell>
                         <span className="block truncate max-w-[120px]">{acc.nickname || '-'}</span>
                       </TableCell>
                       <TableCell>
                         {acc.status === 'active' ? (
                           <Badge
                             className="text-xs border-0"
                             style={{
                               backgroundColor: theme.ui.badgeBg,
                               color: theme.primary,
                             }}
                           >
                             <CheckCircle2 className="size-3 mr-1" />
                             正常
                           </Badge>
                         ) : acc.status === 'rejected' ? (
                           <Badge className="text-xs border-0" style={{ backgroundColor: p0Color + '12', color: p0Color }}>
                             <Ban className="size-3 mr-1" />
                             已拒绝
                           </Badge>
                         ) : (
                           <Badge
                             className="text-xs border-0"
                             style={{
                               backgroundColor: p0Color + '12',
                               color: p0Color,
                             }}
                           >
                             <Ban className="size-3 mr-1" />
                             已禁用
                           </Badge>
                         )}
                      </TableCell>
                        <TableCell className="whitespace-nowrap text-xs text-muted-foreground">
                          {(acc.createdAt || acc.created_at)?.slice(0, 16).replace('T', ' ') || '-'}
                        </TableCell>
                        <TableCell className="whitespace-nowrap text-xs text-muted-foreground">
                          {(acc.lastLogin || acc.last_login_at) ? (acc.lastLogin || acc.last_login_at)!.slice(0, 16).replace('T', ' ') : '未登录'}
                        </TableCell>
                       <TableCell className="tabular-nums">{acc.checkin_days || 0} 天</TableCell>
                      <TableCell className="text-right">
                        <div className="flex items-center justify-end gap-1">
                           <Button
                             variant="ghost"
                             size="sm"
                             className="h-7 text-xs px-2"
                             onClick={() => loadLogs(acc.username)}
                           >
                            <History className="size-3.5 mr-1" />
                            日志
                          </Button>
                           <Button
                             variant="ghost"
                             size="sm"
                             className="h-7 text-xs px-2"
                              onClick={() => {
                                setResetUsername(acc.username);
                                setResetAccountId(acc.id);
                                setResetPassword('');
                                setResetOpen(true);
                              }}
                           >
                            <KeyRound className="size-3.5 mr-1" />
                            重置密码
                          </Button>
                           {acc.status === 'active' ? (
                              <Button
                                variant="ghost"
                                size="sm"
                                className="h-7 text-xs px-2"
                                style={{ color: p0Color }}
                                onClick={() => setConfirmStatus({ username: acc.username, status: 'disabled' })}
                              >
                                <Ban className="size-3.5 mr-1" />
                                禁用
                              </Button>
                            ) : acc.status === 'rejected' ? (
                              <Button
                                variant="ghost"
                                size="sm"
                                className="h-7 text-xs px-2"
                                style={{ color: theme.primary }}
                                onClick={() => setApproveConfirm(acc.username)}
                              >
                                <UserCheck className="size-3.5 mr-1" />
                                重新通过
                              </Button>
                            ) : (
                              <Button
                                variant="ghost"
                                size="sm"
                                className="h-7 text-xs px-2"
                                style={{ color: theme.primary }}
                                onClick={() => setConfirmStatus({ username: acc.username, status: 'active' })}
                              >
                                <CheckCircle2 className="size-3.5 mr-1" />
                                启用
                              </Button>
                            )}
                           {!acc.is_owner && (
                             <Button
                               variant="ghost"
                               size="sm"
                               className="h-7 text-xs px-2"
                               style={{ color: p0Color }}
                               onClick={() => setDeleteConfirm(acc.username)}
                             >
                               删除
                             </Button>
                           )}
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* 新增子账号弹窗 */}
      <Dialog open={addOpen} onOpenChange={setAddOpen}>
        <DialogContent
          className="sm:max-w-md"
          style={{
            backgroundColor: theme.ui.glassBg,
            backdropFilter: 'blur(20px) saturate(180%)',
            WebkitBackdropFilter: 'blur(20px) saturate(180%)',
            borderColor: theme.ui.cardBorder,
          }}
        >
          <DialogHeader>
            <DialogTitle style={{ color: theme.primaryDark }}>
              新增子账号
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-3">
            <div className="space-y-1.5">
              <label className="text-xs font-medium">登录账号 <span className="text-destructive">*</span></label>
              <Input
                value={newUsername}
                onChange={(e) => setNewUsername(e.target.value)}
                placeholder="设置登录用户名"
                autoComplete="username"
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-xs font-medium">昵称</label>
              <Input
                value={newNickname}
                onChange={(e) => setNewNickname(e.target.value)}
                placeholder="显示名称（可选）"
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-xs font-medium">初始密码 <span className="text-destructive">*</span></label>
              <Input
                type="password"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                placeholder="至少6位"
                autoComplete="new-password"
              />
              <p className="text-[10px] text-muted-foreground">
                子账号首次登录后可自行修改密码
              </p>
            </div>
          </div>
          <DialogFooter>
            <Button variant="ghost" size="sm" onClick={() => setAddOpen(false)}>
              取消
            </Button>
            <Button
              size="sm"
              onClick={handleAdd}
              disabled={submitting}
              style={{ backgroundColor: theme.primary }}
            >
              {submitting && <Loader2 className="size-3.5 mr-1.5 animate-spin" />}
              创建
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* 登录日志弹窗 */}
      <Dialog open={logsOpen} onOpenChange={(o) => !o && setLogsOpen(false)}>
        <DialogContent
          className="sm:max-w-lg max-h-[70vh] flex flex-col"
          style={{
            backgroundColor: theme.ui.glassBg,
            backdropFilter: 'blur(20px) saturate(180%)',
            WebkitBackdropFilter: 'blur(20px) saturate(180%)',
            borderColor: theme.ui.cardBorder,
          }}
        >
          <DialogHeader>
            <DialogTitle style={{ color: theme.primaryDark }}>
              登录日志
            </DialogTitle>
          </DialogHeader>
          <div className="flex-1 overflow-y-auto -mx-6 px-6">
            {logsLoading ? (
              <div className="flex items-center justify-center py-12 text-muted-foreground text-sm">
                <Loader2 className="size-4 animate-spin mr-2" />
                加载中...
              </div>
            ) : logs.length === 0 ? (
              <div className="text-center py-12 text-muted-foreground text-sm">
                暂无登录记录
              </div>
            ) : (
              <div className="space-y-2">
                {logs.map((log) => (
                  <div
                    key={log.id}
                    className="flex items-start gap-3 p-3 rounded-lg border"
                    style={{
                      backgroundColor: theme.ui.badgeBg,
                      borderColor: theme.ui.cardBorder,
                    }}
                  >
                    <div
                      className="size-8 rounded-full flex items-center justify-center shrink-0"
                      style={{
                        backgroundColor: log.status === 'success'
                          ? theme.primary + '15'
                          : p0Color + '12',
                      }}
                    >
                      {log.status === 'success' ? (
                        <CheckCircle2 className="size-4" style={{ color: theme.primary }} />
                      ) : log.status === 'kicked' ? (
                        <Ban className="size-4" style={{ color: p0Color }} />
                      ) : (
                        <Ban className="size-4" style={{ color: p0Color }} />
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="text-xs font-medium flex items-center gap-2">
                        <span style={{
                          color: log.status === 'success' ? theme.primary : p0Color,
                        }}>
                          {log.status === 'success' ? '登录成功' :
                            log.status === 'kicked' ? '被挤下线' :
                            log.status === 'failed' ? '登录失败' : log.status}
                        </span>
                      </div>
                      {log.reason && (
                        <div className="text-[11px] text-muted-foreground mt-0.5">
                          {log.reason}
                        </div>
                      )}
                      <div className="text-[11px] text-muted-foreground mt-1 flex items-center gap-3 flex-wrap">
                        <span>IP：{log.ip || '-'}</span>
                        {log.device_fingerprint && (
                          <span className="truncate max-w-[120px]">设备：{log.device_fingerprint}</span>
                        )}
                      </div>
                    </div>
                    <div className="text-[10px] text-muted-foreground whitespace-nowrap shrink-0">
                      {log.created_at?.slice(5, 16) || ''}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </DialogContent>
      </Dialog>

      {/* 重置密码弹窗 */}
      <Dialog open={resetOpen} onOpenChange={(o) => !o && setResetOpen(false)}>
        <DialogContent
          className="sm:max-w-sm"
          style={{
            backgroundColor: theme.ui.glassBg,
            backdropFilter: 'blur(20px) saturate(180%)',
            WebkitBackdropFilter: 'blur(20px) saturate(180%)',
            borderColor: theme.ui.cardBorder,
          }}
        >
          <DialogHeader>
            <DialogTitle style={{ color: theme.primaryDark }}>
              重置密码
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-3">
            <div className="space-y-1.5">
              <label className="text-xs font-medium">新密码 <span className="text-destructive">*</span></label>
              <Input
                type="password"
                value={resetPassword}
                onChange={(e) => setResetPassword(e.target.value)}
                placeholder="至少6位"
                autoComplete="new-password"
              />
              <p className="text-[10px] text-muted-foreground">
                重置后原密码立即失效，同时会挤掉该账号的当前登录
              </p>
            </div>
          </div>
          <DialogFooter>
            <Button variant="ghost" size="sm" onClick={() => setResetOpen(false)}>
              取消
            </Button>
            <Button
              size="sm"
              onClick={handleResetPassword}
              disabled={resetSubmitting}
              style={{ backgroundColor: theme.primary }}
            >
              {resetSubmitting && <Loader2 className="size-3.5 mr-1.5 animate-spin" />}
              确认重置
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* 启用/禁用确认弹窗 */}
      <AlertDialog
        open={!!confirmStatus}
        onOpenChange={(o) => !o && setConfirmStatus(null)}
      >
        <AlertDialogContent
          style={{
            backgroundColor: theme.ui.glassBg,
            backdropFilter: 'blur(20px) saturate(180%)',
            WebkitBackdropFilter: 'blur(20px) saturate(180%)',
            borderColor: theme.ui.cardBorder,
          }}
        >
          <AlertDialogHeader>
            <AlertDialogTitle style={{ color: p0Color }}>
              {confirmStatus?.status === 'active' ? '确认启用该账号？' : '确认禁用该账号？'}
            </AlertDialogTitle>
            <AlertDialogDescription>
              {confirmStatus?.status === 'active'
                ? '启用后该账号可正常登录并使用全部功能。'
                : '禁用后该账号将无法登录，当前登录会话会被立即踢下线。'}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>取消</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleStatusConfirm}
              style={confirmStatus?.status === 'disabled'
                ? { backgroundColor: p0Color }
                : { backgroundColor: theme.primary }}
            >
              确认
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* 删除账号确认弹窗 */}
      <AlertDialog
        open={!!deleteConfirm}
        onOpenChange={(o) => !o && setDeleteConfirm(null)}
      >
        <AlertDialogContent
          style={{
            backgroundColor: theme.ui.glassBg,
            backdropFilter: 'blur(20px) saturate(180%)',
            WebkitBackdropFilter: 'blur(20px) saturate(180%)',
            borderColor: theme.ui.cardBorder,
          }}
        >
          <AlertDialogHeader>
            <AlertDialogTitle style={{ color: p0Color }}>
              确认删除该账号？
            </AlertDialogTitle>
            <AlertDialogDescription>
              删除后账号将彻底清除，无法恢复。该账号的登录记录和数据也将一并删除。
              <div className="mt-2 font-medium text-foreground">
                账号：{deleteConfirm}
              </div>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>取消</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              style={{ backgroundColor: p0Color }}
            >
              确认删除
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* 审批通过确认弹窗 */}
      <AlertDialog
        open={!!approveConfirm}
        onOpenChange={(o) => !o && setApproveConfirm(null)}
      >
        <AlertDialogContent
          style={{
            backgroundColor: theme.ui.glassBg,
            backdropFilter: 'blur(20px) saturate(180%)',
            WebkitBackdropFilter: 'blur(20px) saturate(180%)',
            borderColor: theme.ui.cardBorder,
          }}
        >
          <AlertDialogHeader>
            <AlertDialogTitle style={{ color: theme.primary }}>
              确认通过该账号的注册申请？
            </AlertDialogTitle>
            <AlertDialogDescription>
              通过后该账号可正常登录并使用全部功能。
              <div className="mt-2 font-medium text-foreground">
                账号：{approveConfirm}
              </div>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>取消</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleApprove}
              disabled={approveSubmitting}
              style={{ backgroundColor: theme.primary }}
            >
              {approveSubmitting && <Loader2 className="size-3.5 mr-1.5 animate-spin" />}
              通过
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* 拒绝审批确认弹窗 */}
      <AlertDialog
        open={!!rejectConfirm}
        onOpenChange={(o) => !o && setRejectConfirm(null)}
      >
        <AlertDialogContent
          style={{
            backgroundColor: theme.ui.glassBg,
            backdropFilter: 'blur(20px) saturate(180%)',
            WebkitBackdropFilter: 'blur(20px) saturate(180%)',
            borderColor: theme.ui.cardBorder,
          }}
        >
          <AlertDialogHeader>
            <AlertDialogTitle style={{ color: p0Color }}>
              确认拒绝该账号的注册申请？
            </AlertDialogTitle>
            <AlertDialogDescription>
              拒绝后该账号将无法登录，如需重新激活可手动通过。
              <div className="mt-2 font-medium text-foreground">
                账号：{rejectConfirm}
              </div>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>取消</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleReject}
              disabled={rejectSubmitting}
              style={{ backgroundColor: p0Color }}
            >
              {rejectSubmitting && <Loader2 className="size-3.5 mr-1.5 animate-spin" />}
              拒绝
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
